var currentCapabilities: [String: Bool] {
    var caps: [String: Bool] = [:]
    if hasFDA && !screenTimeDisabled { caps["screentime"] = true }
    if !localFolders.isEmpty { caps["local_directory"] = true }
    if hasHealthKit && healthKitAvailable && !healthKitDisabled { caps["healthkit"] = true }
    if hasPhotos && !photosDisabled { caps["photos"] = true }
    // Advertise system_audio while recording OR while finalized segments
    // still need shipping (so leftover audio drains after the user stops).
    if !systemAudioDisabled && SystemAudioCaptureService.isAvailable()
        && (isRecordingAudio || !SystemAudioCaptureService.shared.pendingSegments().isEmpty) {
        caps["system_audio"] = true
    }
    if hasCalendar && !calendarDisabled { caps["calendar"] = true }
    if hasReminders && !remindersDisabled { caps["reminders"] = true }
    if computerUseActive { caps["computer_use"] = true }
    // os.shell is gated purely by user intent (no TCC preflight exists for
    // it). `shellEnabled` is the opt-in; `shellDisabled` is the kill switch
    // the revoke deep link flips. Both must read true to advertise.
    if shellEnabled && !shellDisabled { caps["os.shell"] = true }
    // Check the WhatsApp archive directly. Tying this to the Screen Time
    // database's FDA probe creates a false negative when WhatsApp's Group
    // Container is readable but Knowledge/knowledgeC.db is not.
    // Cached, never probed inline — see `whatsAppArchiveReadable`. The disable
    // flag is read first so the kill switch works even if the cache is stale.

