/// Handle `owletto://grant/<capability>` fired by the web SPA: clear any
/// soft-disable and present the native permission prompt (only the signed
/// app can). The capability advertises on the next poll once granted, and
/// device-reconcile wires its feed server-side — the same path the menubar
/// toggles used to drive.
func grantCapability(_ capability: String) {
    switch capability {
    case "calendar":
        calendarDisabled = false
        if hasCalendar { setStatus("Calendar already connected.") }
        else { Task { await requestCalendarAccess() } }
    case "reminders":
        remindersDisabled = false
        if hasReminders { setStatus("Reminders already connected.") }
        else { Task { await requestRemindersAccess() } }
        else { openFullDiskAccessSettings() }
    case "whatsapp_local":
        whatsAppDisabled = false
        // Probe off the main actor — this call is what shows the TCC dialog,
        // and it must not park the app while the user reads it.
        refreshWhatsAppAvailability(force: true)
        setStatus("Checking the WhatsApp archive…")
    case "os.shell":
        shellDisabled = false
        shellEnabled = true
        setStatus("Shell enabled — commands will run as your user.")
        Task { await syncNow() }
    case "computer_use":
        computerUseDisabled = false
        computerUseEnabled = true
        if computerUseReadyForDeviceActions() {
            UserDefaults.standard.removeObject(forKey: Self.computerUseLastGrantPromptKey)
            if computerUseAccessibilityGranted() {
                setStatus("Computer use already connected.")
            } else {
                setStatus("Computer use connected. Enable Accessibility for click/type actions.")

