  const conns = await client.connections.list({ connector_key: "os.shell" });
  const conn = Array.isArray(conns) ? conns[0] : (conns?.items ?? conns?.data ?? [])[0];
  if (!conn) return { error: "no os.shell connection", conns };

  const probe = [
    'echo "user=$(whoami)  uid=$(id -u)  shell=$SHELL"',
    'echo "sandbox_container=${APP_SANDBOX_CONTAINER_ID:-<none>}"',
    'for d in "$HOME" "$HOME/Code" /tmp /usr/bin "$HOME/Desktop" "$HOME/Documents" "$HOME/Downloads" "$HOME/Library/Messages" "$HOME/Library/Application Support/com.apple.TCC"; do',
    '  if ls "$d" >/dev/null 2>&1; then echo "READABLE  $d"; else echo "DENIED    $d"; fi',
    'done',
  ].join("\n");

  const run = await client.operations.execute({
    connection_id: conn.id,
    operation_key: "run",
    input: { command: probe, timeout_ms: 30000 },
  });
  return { connection_id: conn.id, run };
};

