  const res = await client.connections.list({});
  const mini = res.connections.filter(
    (c) => c.device_worker_handle === "mac-e74661e8-f5c8-417a-927e-56b6c2fe1089"
  );
  const out = [];
  for (const c of mini) {
    let ops = null;
    if (c.has_operations) {
      try {
        const listed = await client.operations.listAvailable({ connector_key: c.connector_key });
        ops = (listed.operations ?? listed).map((o) => ({
          key: o.operation_key ?? o.key,
          kind: o.kind,
          requires_approval: o.requires_approval,
        }));
      } catch (e) {
        ops = `err: ${String(e)}`;
      }
    }
    out.push({
      id: c.id,
      connector_key: c.connector_key,
      slug: c.slug,
      status: c.status,
      config: c.config,
      has_operations: c.has_operations,
      ops,
    });
  }
  return out;
};

