        timeoutHint =
            "Owletto has no Full Disk Access, so this may be a TCC stall rather than a slow "
            + "command: reading Desktop/Documents/Downloads/~/Library blocks on a consent "
            + "prompt nobody can answer on an unattended Mac. Grant Full Disk Access to "
            + "Owletto, or keep the command off those paths. Raising timeout_ms will not help."
