@main
struct ShellTimeoutHintTests {
    static var failures = 0

    static func expect(_ condition: Bool, _ what: String) {
        if condition {
            print("  ok   \(what)")
        } else {
            print("  FAIL \(what)")
            failures += 1
        }
    }

    static func main() {
        print("ShellTimeoutHintTests")

        // The whole point: a timeout with no FDA must explain itself.
        let stalled = MacShellActionService.timeoutHint(
            timedOut: true, hasFullDiskAccess: false
        )
        expect(stalled != nil, "timed out without FDA -> hint present")

        // It must name the remedy AND rule out the wrong one. Agents reaching for
        // timeout_ms is the exact failure this text exists to stop.
        expect(
            stalled?.contains("Full Disk Access") == true,
            "hint names Full Disk Access as the remedy"
        )
        expect(
            stalled?.contains("timeout_ms") == true,
            "hint says raising timeout_ms will not help"
        )
        // Hedged: this cannot distinguish a TCC stall from a genuinely slow
        // command, and must not claim it can.
        expect(stalled?.contains("may be") == true, "hint is hedged, not asserted")

        // Silence in every other combination — a hint that always fires is noise.
        expect(
            MacShellActionService.timeoutHint(timedOut: true, hasFullDiskAccess: true) == nil,
            "timed out WITH FDA -> no hint (not a TCC stall)"
        )
        expect(
            MacShellActionService.timeoutHint(timedOut: false, hasFullDiskAccess: false) == nil,
            "completed without FDA -> no hint (nothing to explain)"
        )
        expect(
            MacShellActionService.timeoutHint(timedOut: false, hasFullDiskAccess: true) == nil,
            "completed with FDA -> no hint"
        )

        if failures == 0 {
            print("PASS")
        } else {
            print("FAIL (\(failures))")
            exit(1)
        }
    }
}

