import Combine
import Foundation
import Sparkle

/// SwiftUI-friendly wrapper around `SPUStandardUpdaterController`. Sparkle's
/// own controller is an `NSObject` and exposes its state via `@objc` properties
/// — wrap it as an `@MainActor` `ObservableObject` so the menubar view can
/// observe `canCheckForUpdates`, `updateAvailable`, and `latestVersion`.
///
/// Auto-checks fire silently in the background; the standard user driver shows
/// a small "Update available" prompt that users can accept or defer. When the
/// user clicks the menu row, `checkForUpdates()` triggers an explicit check.
@MainActor
final class OwlettoUpdater: NSObject, ObservableObject {
    @Published private(set) var canCheckForUpdates = false
    @Published private(set) var updateAvailable = false
    @Published private(set) var latestVersion: String?

    private var controller: SPUStandardUpdaterController!

    /// Singleton because Sparkle holds a long-lived XPC connection per process
    /// and the standard user driver wires itself to the main menu / dock.
    static let shared = OwlettoUpdater()

    private override init() {
        super.init()
        // Delegate must be wired at construction time — `SPUUpdater.delegate`
        // is read-only in Sparkle 2.x.
        //
        // Local DEBUG builds are stamped MARKETING_VERSION=0.1.0 (CI overrides
        // it per release tag), so a started updater would always see the
        // published release as "newer" and nag "Update to vX.Y.Z" — a bogus
        // prompt that also can't install cleanly over a DerivedData dev build.
        // Don't start the scheduled updater in DEBUG. We gate on startup rather
        // than the persisted `automaticallyChecksForUpdates` pref because that
        // pref lives in the shared `com.owletto.mac` UserDefaults domain and
        // would leak the disabled state into the Release app.
        #if DEBUG
        let startingUpdater = false
        #else
        let startingUpdater = true
        #endif
        self.controller = SPUStandardUpdaterController(
            startingUpdater: startingUpdater, updaterDelegate: self, userDriverDelegate: nil
        )
        // Mirror Sparkle's KVO state through @Published.
        controller.updater.publisher(for: \.canCheckForUpdates)
            .receive(on: DispatchQueue.main)
            .sink { [weak self] in self?.canCheckForUpdates = $0 }
            .store(in: &cancellables)
    }

    private var cancellables = Set<AnyCancellable>()

    /// Triggered by the menubar "Update to vX.Y.Z" row. Falls back to a silent
    /// `checkForUpdates()` so Sparkle's UI takes over (download + relaunch).
    func checkForUpdates() {
        controller.checkForUpdates(nil)
    }
}

// MARK: - SPUUpdaterDelegate

extension OwlettoUpdater: SPUUpdaterDelegate {
    nonisolated func updater(_ updater: SPUUpdater, didFindValidUpdate item: SUAppcastItem) {
        Task { @MainActor in
            self.updateAvailable = true
            self.latestVersion = item.displayVersionString
        }
    }

    nonisolated func updaterDidNotFindUpdate(_ updater: SPUUpdater) {
        // Use the installed version as the "latest seen" so the menu-bar
        // footer can flip from "Checking…" to "Up to date" — otherwise the
        // status sticks at "Checking…" forever after a successful check that
        // returned no newer release.
        let current = Bundle.main
            .infoDictionary?["CFBundleShortVersionString"] as? String
        Task { @MainActor in
            self.updateAvailable = false
            self.latestVersion = current
        }
    }

    nonisolated func updater(_ updater: SPUUpdater, didAbortWithError error: Error) {
        // Same idea on network errors / appcast parse failures: surface "Up to
        // date" rather than wedging the UI. Sparkle has already logged the
        // detail; the menu-bar footer doesn't need to spell it out.
        let current = Bundle.main
            .infoDictionary?["CFBundleShortVersionString"] as? String
        Task { @MainActor in
            self.latestVersion = current
        }
    }
}

