import Foundation

/// When it is safe to let Sparkle swap the bundle and relaunch.
///
/// Installing a staged update terminates this process, so the decision is
/// destructive and cannot be retried against the work it interrupts. It lives
/// here — free of Sparkle, SwiftUI and the app graph — so the rule can be
/// exercised directly by `apps/mac/Tests/StagedUpdateGateTests.swift` instead
/// of being argued about in prose.
///
/// The bar is not "is the app quiet" but "would terminating right now destroy
/// state that a relaunch cannot rebuild". Anything already durable on disk (a
/// finalized audio segment awaiting upload, a queued job the server will hand
/// out again) does NOT block: the relaunched app picks it up. Only live,
/// in-memory work does.
enum StagedUpdateGate {
    /// Live work that a termination would destroy. One field per thing that
    /// cannot survive a relaunch — adding a new long-running local activity
    /// means adding it here.
    struct Activity {
        /// Behavior runs claimed by this device and executing locally. A claim
        /// outlives the process, so quitting mid-run strands the run until the
        /// server's heartbeat-stale reaper takes it back — minutes of a visibly
        /// stuck run, and a wasted CLI turn.
        var behaviorRunsInFlight: Int = 0

        /// A live system-audio capture session. This one is not self-healing:
        /// recording starts only from an explicit grant or deep-link and is
        /// never resumed at launch, so a relaunch would leave the Mac silently
        /// not recording until a human noticed and re-armed it. Segments
        /// already finalized on disk are safe and ship later regardless.
        var isRecordingAudio: Bool = false

        var isIdle: Bool { behaviorRunsInFlight == 0 && !isRecordingAudio }
    }

    /// `true` only when an update is actually staged AND nothing live would be
    /// lost. Deliberately conservative: a deferred install costs one more poll
    /// interval, an install at the wrong moment costs a stranded run or a
    /// recording that silently stopped.
    static func shouldInstall(staged: Bool, activity: Activity) -> Bool {
        staged && activity.isIdle
    }

    /// Why an install was held, for the log. `nil` when it proceeded, so the
    /// caller can log the reason without re-deriving it.
    static func deferralReason(staged: Bool, activity: Activity) -> String? {
        guard staged, !activity.isIdle else { return nil }
        var reasons: [String] = []
        if activity.behaviorRunsInFlight > 0 {
            reasons.append("\(activity.behaviorRunsInFlight) behavior run(s) in flight")
        }
        if activity.isRecordingAudio { reasons.append("system-audio capture is live") }
        return reasons.joined(separator: ", ")
    }
}

