        staged && activity.isIdle
    }

    /// Why an install was held, for the log. `nil` when it proceeded, so the
    /// caller can log the reason without re-deriving it.
    static func deferralReason(staged: Bool, activity: Activity) -> String? {
        guard staged, !activity.isIdle else { return nil }
        var reasons: [String] = []
        if activity.behaviorRunsInFlight > 0 {
            reasons.append("\(activity.behaviorRunsInFlight) behavior run(s) in flight")
        }
        if activity.isRecordingAudio { reasons.append("system-audio capture is live") }
        return reasons.joined(separator: ", ")
    }
}

