// Standalone regression test for the staged-update idle gate.
//
// Sparkle installs by terminating this process and swapping the bundle, so the
// gate's decision is destructive and un-retryable against whatever it
// interrupts. A menubar app on an unattended Mac never quits on its own, which
// is why the gate exists at all: measured 2026-07-31 on the Mac mini, TWO fully
// staged updates (14.5.0 from 28 Jul, 14.8.0 from 31 Jul) had been parked
// without ever installing.
//
// The failure this pins down is the opposite one — installing too eagerly. The
// original patch fired whenever the poll loop's drain exited, treating "the
// server had nothing left to hand out" as "nothing is running". It is not:
// a claimed Behavior run outlives the process, and a live system-audio capture
// never resumes at launch. So the gate must hold on live work and must NOT hold
// on anything a relaunch rebuilds by itself.
//
//   swiftc apps/mac/Owletto/StagedUpdateGate.swift \
//          apps/mac/Tests/StagedUpdateGateTests.swift -o /tmp/staged-update-gate-test \
//   && /tmp/staged-update-gate-test

import Foundation

@main
struct StagedUpdateGateTests {
    static var failures = 0

    static func expect(_ condition: Bool, _ what: String) {
        if condition {
            print("  ok   \(what)")
        } else {
            print("  FAIL \(what)")
            failures += 1
        }
    }

    static func main() {
        print("StagedUpdateGateTests")

        let idle = StagedUpdateGate.Activity()

        // The whole point of the change: an idle device must actually install,
        // otherwise updates park forever as they did on the mini.
        expect(
            StagedUpdateGate.shouldInstall(staged: true, activity: idle),
            "staged + idle -> install"
        )

        // Nothing staged is the overwhelmingly common case and must never fire.
        expect(
            !StagedUpdateGate.shouldInstall(staged: false, activity: idle),
            "nothing staged -> no install, even when idle"
        )

        // A claimed run outlives the process: quitting strands it on the server
        // until the heartbeat-stale reaper takes it back.
        expect(
            !StagedUpdateGate.shouldInstall(
                staged: true, activity: .init(behaviorRunsInFlight: 1)
            ),
            "behavior run in flight -> hold"
        )
        // Queued-behind-in-flight counts too; `claimedRunCount` folds both,
        // and a queued job is already claimed.
        expect(
            !StagedUpdateGate.shouldInstall(
                staged: true, activity: .init(behaviorRunsInFlight: 3)
            ),
            "several claimed runs -> hold"
        )

        // Recording is the non-self-healing one: it only starts from an explicit
        // grant or deep-link, so a relaunch leaves the Mac silently not
        // recording. This is the case a "no runs in flight" check alone misses.
        expect(
            !StagedUpdateGate.shouldInstall(
                staged: true, activity: .init(isRecordingAudio: true)
            ),
            "system-audio capture live -> hold"
        )
        expect(
            !StagedUpdateGate.shouldInstall(
                staged: true, activity: .init(behaviorRunsInFlight: 2, isRecordingAudio: true)
            ),
            "both live -> hold"
        )

        // A deferral that logs nothing is one nobody can diagnose from the mini,
        // where these decisions are only ever observed after the fact.
        let bothReason = StagedUpdateGate.deferralReason(
            staged: true, activity: .init(behaviorRunsInFlight: 2, isRecordingAudio: true)
        )
        expect(bothReason?.contains("2 behavior run") == true, "reason names the run count")
        expect(bothReason?.contains("system-audio") == true, "reason names the recording")

        // No reason when nothing was held — the caller logs only on a deferral,
        // so a non-nil here would print "held" on an install that proceeded.
        expect(
            StagedUpdateGate.deferralReason(staged: true, activity: idle) == nil,
            "idle -> no deferral reason"
        )
        expect(
            StagedUpdateGate.deferralReason(
                staged: false, activity: .init(isRecordingAudio: true)
            ) == nil,
            "nothing staged -> no deferral reason (nothing was held)"
        )

        if failures == 0 {
            print("PASS")
        } else {
            print("FAIL (\(failures))")
            exit(1)
        }
    }
}

