import AppKit
import ApplicationServices
import Foundation
import UserNotifications

/// OS / session capabilities Owletto needs for device work.
/// Status is probed live — never cached in UserDefaults (TCC can change
/// in System Settings without notifying the app).
enum DevicePermissionKind: String, CaseIterable, Identifiable {
    /// Screen capture (window list, screenshots, system audio).
    case screenRecording
    /// Accessibility + event synthesize — click/type for computer use.
    /// Shown as one chip so we don't have a vague "Access" label next to "Input".
    case control
    /// Full Disk Access for Screen Time / WhatsApp archive.
    case fullDiskAccess
    /// Banner notifications (optional; not requested anywhere else yet).
    case notifications
    /// Login item — start Owletto after reboot (Open at Login).
    case openAtLogin

    var id: String { rawValue }

    var title: String {
        switch self {
        case .screenRecording: return "Screen Recording"
        case .control: return "Click & Type"
        case .fullDiskAccess: return "Full Disk Access"
        case .notifications: return "Notifications"
        case .openAtLogin: return "Open at Login"
        }
    }

    var subtitle: String {
        switch self {
        case .screenRecording:
            return "Window list, screenshots, system audio"
        case .control:
            return "Computer-use click and type (Accessibility)"
        case .fullDiskAccess:
            return "Screen Time and WhatsApp archive"
        case .notifications:
            return "Desktop banners when something needs attention"
        case .openAtLogin:
            return "Start Owletto after you log in so the device stays online"
        }
    }

    var isRequiredForComputerUse: Bool {
        switch self {
        case .screenRecording, .control: return true
        case .fullDiskAccess, .notifications, .openAtLogin: return false
        }
    }

    /// Names of the underlying TCC services this chip needs that are NOT
    /// currently granted. Empty means fully granted.
    ///
    /// `.control` is the reason this exists: it ANDs two *distinct* TCC
    /// services (Accessibility and PostEvent) behind a single dot, so a user
    /// who has granted one of them sees "not granted" with no way to tell
    /// which half is missing. Naming the gap is the difference between a
    /// two-minute fix and an hour of guessing.
    var unmetRequirements: [String] {
        switch self {
        case .control:
            var missing: [String] = []
            if !AXIsProcessTrusted() { missing.append("Accessibility") }
            if !CGPreflightPostEventAccess() { missing.append("Event Synthesizing") }
            return missing
        default:
            return isGranted ? [] : [title]
        }
    }

    var isGranted: Bool {
        switch self {
        case .screenRecording:
            return CGPreflightScreenCaptureAccess()
        case .control:
            // Both gates are needed for full computer use; Accessibility pane
            // covers both in System Settings.
            return AXIsProcessTrusted() && CGPreflightPostEventAccess()
        case .fullDiskAccess:
            return DevicePermissionKind.probeFullDiskAccess()
        case .notifications:
            // Synchronous cache updated by refreshNotificationStatus() / grant.
            return DevicePermissionKind.notificationsAuthorized
        case .openAtLogin:
            return OpenAtLogin.isEnabled
        }
    }

    /// Cached UN authorization — UN APIs are async; keep a snapshot for UI.
    private static var notificationsAuthorized = false

    /// Call on menubar appear / after grant so chips stay honest.
    static func refreshNotificationStatus() async {
        let settings = await UNUserNotificationCenter.current().notificationSettings()
        let ok: Bool
        switch settings.authorizationStatus {
        case .authorized, .provisional, .ephemeral:
            ok = true
        default:
            ok = false
        }
        await MainActor.run {
            notificationsAuthorized = ok
        }
    }

    private static func probeFullDiskAccess() -> Bool {
        let knowledge = URL(fileURLWithPath: NSHomeDirectory())
            .appendingPathComponent("Library/Application Support/Knowledge/knowledgeC.db")
        if FileManager.default.isReadableFile(atPath: knowledge.path) {
            return true
        }
        let groupContainers = URL(fileURLWithPath: NSHomeDirectory())
            .appendingPathComponent("Library/Group Containers")
        guard let contents = try? FileManager.default.contentsOfDirectory(
            at: groupContainers,
            includingPropertiesForKeys: nil
        ) else {
            return false
        }
        return contents.contains { $0.lastPathComponent.contains("net.whatsapp.WhatsApp") }
    }

    var settingsURL: URL? {
        switch self {
        case .screenRecording:
            return URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy_ScreenCapture")
        case .control:
            return URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility")
        case .fullDiskAccess:
            return URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy_AllFiles")
        case .notifications:
            // Notifications pane (Ventura+ style URL; falls back gracefully).
            return URL(string: "x-apple.systempreferences:com.apple.Notifications-Settings.extension")
                ?? URL(string: "x-apple.systempreferences:com.apple.preference.notifications")
        case .openAtLogin:
            return URL(string: "x-apple.systempreferences:com.apple.LoginItems-Settings.extension")
        }
    }

    /// Grant when off; when on, open Settings so the user can revoke (macOS
    /// does not allow apps to drop TCC themselves — only Login Item can be
    /// unregistered in-process).
    @discardableResult
    func requestGrant() -> String {
        switch self {
        case .screenRecording:
            if isGranted {
                return openSettingsToRevoke(
                    "Uncheck Owletto under Screen Recording to turn it off."
                )
            }
            _ = CGRequestScreenCaptureAccess()
            if isGranted { return "Screen Recording granted." }
            if let url = settingsURL { NSWorkspace.shared.open(url) }
            return "Enable Owletto under Screen Recording in System Settings."
        case .control:
            if isGranted {
                return openSettingsToRevoke(
                    "Uncheck Owletto under Accessibility to turn off click & type."
                )
            }
            let opts = [kAXTrustedCheckOptionPrompt.takeUnretainedValue() as String: true] as CFDictionary
            _ = AXIsProcessTrustedWithOptions(opts)
            if isGranted { return "Click & Type control granted." }
            if let url = settingsURL { NSWorkspace.shared.open(url) }
            // Name the half that is still missing. Granting Accessibility does
            // not always carry PostEvent with it, and when it doesn't the user
            // is looking at a switch that is already on.
            let missing = unmetRequirements
            if missing == ["Event Synthesizing"] {
                return "Accessibility is on but Event Synthesizing is not — "
                    + "remove Owletto from Accessibility and re-add it."
            }
            return "Enable Owletto under Accessibility for click and type"
                + (missing.isEmpty ? "." : " (missing: \(missing.joined(separator: ", "))).")
        case .fullDiskAccess:
            if isGranted {
                return openSettingsToRevoke(
                    "Uncheck Owletto under Full Disk Access to turn it off."
                )
            }
            if let url = settingsURL { NSWorkspace.shared.open(url) }
            return "Add Owletto under Full Disk Access in System Settings."
        case .notifications:
            if isGranted {
                return openSettingsToRevoke(
                    "Turn off Owletto under Notifications to stop banners."
                )
            }
            Task {
                let center = UNUserNotificationCenter.current()
                do {
                    let ok = try await center.requestAuthorization(options: [.alert, .sound, .badge])
                    await MainActor.run {
                        DevicePermissionKind.notificationsAuthorized = ok
                    }
                    if !ok, let url = settingsURL {
                        await MainActor.run { NSWorkspace.shared.open(url) }
                    }
                } catch {
                    if let url = settingsURL {
                        await MainActor.run { NSWorkspace.shared.open(url) }
                    }
                }
            }
            return "Requesting notification permission…"
        case .openAtLogin:
            // Login Item is the one we can fully toggle without System Settings.
            OpenAtLogin.hasAsked = true
            if isGranted {
                _ = OpenAtLogin.setEnabled(false)
                return "Open at Login turned off."
            }
            if OpenAtLogin.setEnabled(true) {
                return "Open at Login on — Owletto will start after you log in."
            }
            if let url = settingsURL { NSWorkspace.shared.open(url) }
            return "Couldn't register Open at Login — check Login Items in System Settings."
        }
    }

    private func openSettingsToRevoke(_ message: String) -> String {
        if let url = settingsURL { NSWorkspace.shared.open(url) }
        return message
    }
}

