private func permissionRow(kind: DevicePermissionKind) -> some View {
    let granted = kind.isGranted
    return Button {
        let msg = kind.requestGrant()
        // Empty msg = already granted / chip state is enough — no status spam.
        if !msg.isEmpty { state.setStatus(msg) }
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 500_000_000)
            if kind == .notifications {
                await DevicePermissionKind.refreshNotificationStatus()
            }
            permissionsRefreshToken &+= 1
            if kind == .screenRecording || kind == .control {
                state.computerUseEnabled = true
                state.computerUseDisabled = false
                await state.syncNow()
            }
        }
    } label: {
        HStack(spacing: 6) {
            Text(kind.title)
                .font(.caption)
                .foregroundStyle(granted ? .primary : .secondary)
                .lineLimit(1)
            // Takes the slack, so the row is exactly as wide as the popover
            // and never wider — see the note in `permissionsSection`.
            Spacer(minLength: 8)
            // Status sits on the right, matching the other rows in this
            // menu. No chip fill or border: five bordered pills read as a
            // grid of boxes, and colour alone carries "needs attention".
            Image(systemName: granted ? "checkmark.circle.fill" : "circle")
                .font(.caption)
                .foregroundStyle(granted ? .green : (kind.isRequiredForComputerUse ? .orange : .secondary))
        }
        .contentShape(Rectangle())
        .help(permissionTooltip(kind: kind, granted: granted))
    }
    .buttonStyle(.plain)
    .menuRow()
}

/// Tooltip text for a permission chip. When a chip is off and backed by more
/// than one TCC service, say which service is missing — otherwise "Click &
/// Type is off" is unactionable for a user who already flipped a switch.
private func permissionTooltip(kind: DevicePermissionKind, granted: Bool) -> String {
    if granted {
        return kind == .openAtLogin
            ? "\(kind.title): on — click to turn off."
            : "\(kind.title): on — click to open System Settings and uncheck Owletto."
    }
    let missing = kind.unmetRequirements
    let detail = missing.count > 1 || missing != [kind.title]
