import Foundation

/// Recovering a TCC grant that macOS is refusing because the stored record no
/// longer matches this build's code signature.
///
/// TCC stores a *code requirement* alongside each approval and re-checks it on
/// every access. Toggling the checkbox in System Settings only flips the
/// approval bit — it never rewrites that requirement. So once a record is
/// written against one signing identity, a build signed with another can never
/// satisfy it, and no amount of unchecking and re-checking helps. The row keeps
/// showing "on" while every request is denied.
///
/// Measured on the Mac mini 2026-08-01, from `tccd`:
///
///     Failed to match existing code requirement for subject com.owletto.mac
///                                         and service kTCCServiceAccessibility
///       identifier "com.owletto.mac" and anchor apple generic and
///       certificate leaf[subject.CN] = "Apple Development: … (8NVN2W85G3)"
///
/// The installed app was `Developer ID Application … (CCV9Q352W3)`. The grant
/// had been given to a debug build, which poisoned the record for every release
/// build afterwards. Deleting the record is the only fix; then the next request
/// writes a fresh one against the identity that is actually running.
///
/// Worth knowing which direction this cuts: a Developer ID app's designated
/// requirement is team-ID based (`certificate leaf[subject.OU] = CCV9Q352W3`),
/// with no cdhash in it, so a grant given to a Developer ID build survives every
/// later rebuild, bundle swap and notarized release. This only bites when a
/// grant crosses *certificate classes* — which is why granting TCC to a
/// DerivedData debug build is the thing to never do.
enum TccRepair {
    /// Services as `tccutil` names them — NOT the `kTCCService…` constants.
    /// `tccutil` exits 0 on a name it does not recognise, so a typo here is a
    /// silent no-op; `TccRepairTests` pins these strings for that reason.
    enum Service: String, CaseIterable {
        case screenCapture = "ScreenCapture"
        case accessibility = "Accessibility"
        case postEvent = "PostEvent"
    }

    /// Whether to reset before re-requesting.
    ///
    /// Only when the permission is missing *and* we have asked for it before:
    /// the first request is how a legitimate record gets created, so resetting
    /// then would delete the approval the user is in the middle of giving. A
    /// second request that still finds the permission missing is the signal —
    /// either the user declined (a reset costs nothing, the prompt returns) or
    /// the record is unsatisfiable (a reset is the only way out).
    ///
    /// Never fires while the permission is granted, so a working approval is
    /// never destroyed.
    static func shouldReset(isGranted: Bool, hasRequestedBefore: Bool) -> Bool {
        !isGranted && hasRequestedBefore
    }

    /// argv for one reset. Bundle ID is required — bare `tccutil reset <svc>`
    /// wipes that service for **every** app on the Mac.
    static func arguments(service: Service, bundleID: String) -> [String] {
        ["reset", service.rawValue, bundleID]
    }

    /// Delete the stored records so the next request writes fresh ones.
    /// Returns the services that reset cleanly. Needs no privilege escalation —
    /// a user resetting their own approvals is not an admin operation.
    @discardableResult
    static func reset(services: [Service], bundleID: String) -> [Service] {
        services.filter { service in
            let process = Process()
            process.executableURL = URL(fileURLWithPath: "/usr/bin/tccutil")
            process.arguments = arguments(service: service, bundleID: bundleID)
            process.standardOutput = FileHandle.nullDevice
            process.standardError = FileHandle.nullDevice
            do {
                try process.run()
                process.waitUntilExit()
            } catch {
                Log.error(.app, "tccutil reset \(service.rawValue) failed to launch: \(error)")
                return false
            }
            let ok = process.terminationStatus == 0
            Log.info(.app, "tccutil reset \(service.rawValue) → exit \(process.terminationStatus)")
            return ok
        }
    }

    /// What to tell the user after a repair. macOS caches a denial for the
    /// lifetime of the process, so a grant given after this may not register
    /// until Owletto restarts — saying so up front beats the user concluding
    /// the repair failed and toggling the row again.
    static func message(reset services: [Service], title: String) -> String {
        guard !services.isEmpty else {
            return "Couldn't reset \(title) — open System Settings and remove Owletto, then re-add it."
        }
        return "\(title) was approved for a different build of Owletto, so macOS was refusing it. "
            + "Cleared it — approve the prompt (or tick Owletto in System Settings), "
            + "then quit and reopen Owletto if the light stays orange."
    }
}

