// Standalone regression test for the stale-TCC-record repair.
//
// TCC stores a code requirement with each approval and re-checks it on every
// access; the System Settings checkbox only flips the approval bit and never
// rewrites that requirement. So a record written against one signing identity
// can never be satisfied by a build signed with another, and re-ticking the box
// does nothing — forever. Measured on the Mac mini 2026-08-01: the record
// pinned `Apple Development … (8NVN2W85G3)` while the installed app was
// `Developer ID Application … (CCV9Q352W3)`, and toggling the row was tried and
// did not help. Only deleting the record does.
//
// Two things here can fail silently and neither shows up at runtime:
//
//   1. `tccutil` exits 0 for a service name it does not recognise, so a typo in
//      a raw value is a no-op that still reports success.
//   2. `tccutil reset <service>` WITHOUT a bundle id resets that service for
//      every app on the Mac. The bundle id is not optional polish.
//
// And the reset must never fire while a permission is granted, or clicking a
// working chip would revoke it.
//
//   swiftc apps/mac/Owletto/TccRepair.swift \
//          apps/mac/Tests/TccRepairTests.swift -o /tmp/tcc-repair-test \
//   && /tmp/tcc-repair-test

import Foundation

// TccRepair logs through the app's Log helper; the standalone binary has no
// app graph, so stub the two levels it touches.
enum LogCategory { case app }
enum Log {
    static func info(_ category: LogCategory, _ message: String) {}
    static func error(_ category: LogCategory, _ message: String) {}
}

@main
struct TccRepairTests {
    static var failures = 0

    static func expect(_ condition: Bool, _ what: String) {
        if condition {
            print("  ok   \(what)")
        } else {
            print("  FAIL \(what)")
            failures += 1
        }
    }

    static func main() {
        print("TccRepairTests")

        // --- when the reset fires ------------------------------------------

        // The case this exists for: asked before, still not granted.
        expect(
            TccRepair.shouldReset(isGranted: false, hasRequestedBefore: true),
            "missing after a previous request -> reset"
        )
        // A first request is how a legitimate record gets created. Resetting
        // then would delete the approval the user is mid-way through giving.
        expect(
            !TccRepair.shouldReset(isGranted: false, hasRequestedBefore: false),
            "first request -> no reset (the record is being created)"
        )
        // Never destroy a working approval, whatever the history says.
        expect(
            !TccRepair.shouldReset(isGranted: true, hasRequestedBefore: true),
            "granted -> never reset"
        )
        expect(
            !TccRepair.shouldReset(isGranted: true, hasRequestedBefore: false),
            "granted and never asked -> never reset"
        )

        // --- argv ------------------------------------------------------------

        // Pinned literally: tccutil exits 0 on an unrecognised service name, so
        // a typo here would silently reset nothing and report success.
        expect(TccRepair.Service.screenCapture.rawValue == "ScreenCapture", "ScreenCapture spelling")
        expect(TccRepair.Service.accessibility.rawValue == "Accessibility", "Accessibility spelling")
        expect(TccRepair.Service.postEvent.rawValue == "PostEvent", "PostEvent spelling")

        let argv = TccRepair.arguments(service: .screenCapture, bundleID: "com.owletto.mac")
        expect(argv == ["reset", "ScreenCapture", "com.owletto.mac"], "argv shape")
        // The dangerous omission: no bundle id resets the service for EVERY app.
        expect(argv.count == 3, "argv always carries a bundle id")
        expect(argv.last == "com.owletto.mac", "bundle id is last")

        // Every service must be reachable from the argv builder — a case added
        // to the enum but never mapped would be a permission that cannot repair.
        for service in TccRepair.Service.allCases {
            expect(
                TccRepair.arguments(service: service, bundleID: "x") == ["reset", service.rawValue, "x"],
                "argv for \(service.rawValue)"
            )
        }

        // --- what the user is told ------------------------------------------

        let ok = TccRepair.message(reset: [.screenCapture], title: "Screen Recording")
        // Must explain WHY the switch they already flipped did nothing.
        expect(ok.contains("different build"), "success message explains the cause")
        // macOS caches the denial for the process lifetime, so a grant given now
        // may not register until relaunch. Omitting that reads as a failed fix.
        expect(ok.contains("quit and reopen"), "success message warns a restart may be needed")

        let failed = TccRepair.message(reset: [], title: "Screen Recording")
        expect(failed.contains("Couldn't reset"), "empty reset -> failure message")
        expect(!failed.contains("Cleared it"), "failure message does not claim success")

        if failures == 0 {
            print("PASS")
        } else {
            print("FAIL (\(failures))")
            exit(1)
        }
    }
}

