/// Handle `owletto://revoke/<capability>`: set the soft-disable flag so the
/// capability stops being advertised on the next poll; device-reconcile
/// then pauses the feed (it's never deleted, just paused).
func revokeCapability(_ capability: String) {
    switch capability {
    case "calendar": calendarDisabled = true
    case "reminders": remindersDisabled = true
    case "photos": photosDisabled = true
    case "healthkit": healthKitDisabled = true
    case "system_audio":
        systemAudioDisabled = true
        if isRecordingAudio { Task { await stopAudioRecording() } }
    case "screentime": screenTimeDisabled = true
    case "whatsapp_local": whatsAppDisabled = true
    case "computer_use":
        computerUseDisabled = true
        computerUseEnabled = false
    case "os.shell":
        shellDisabled = true
    default: break
    }
}

/// Open System Settings → Privacy & Security → Full Disk Access. Screen Time
/// and WhatsApp both read FDA-gated files and have no in-app TCC prompt.
func openFullDiskAccessSettings() {
    if let url = URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy_AllFiles") {
        NSWorkspace.shared.open(url)
        setStatus("Opening System Settings → Privacy → Full Disk Access…")
    }
}

